require_once '../../../includes/rutas.php';
require_once '../../../libs/mysql.class.php';

$sql = new Conectar();
$tmp = new Conectar();
$tmp2 = new Conectar();

switch ($_GET["a"]) {
    case "1": //saca una ruta en base a acceso_id_inicial
        //devuelve cadena separada por ;; cada valor, dentro de cada valor las variables separadas por ,,  las variables 
        //significan: id_acceso,created_acceso,x_camara,y_camara,
        
        $acceso_id_inicial=$_GET["acceso_id_inicial"];
        $return="";
        $camaras_pasadas=[$acceso_id_inicial];
        
        
        $sql->Consultar("accesos", "*", "id=".$acceso_id_inicial);
        $user_id=$sql->row["user_id"];
        $return=$sql->row["id"].",,".$sql->row["created"];
        $sql->Consultar("camaras", "*", "id=".$sql->row["camara_id"]);
        $return.=",,".$sql->row["x"].",,".$sql->row["y"].";;";
        
        
        $esta_dentro=true;
        $tmp->Consultar("accesos","*","id>".$acceso_id_inicial." and user_id=".$user_id,"id asc",false);
        if($tmp->num>0){
            do{
                //echo "paso:".$tmp->row["id"]."\n";
                $tmp2->Consultar("camaras","*","id=".$tmp->row["camara_id"]);
                
                $created=$tmp->row["created"];
                $y=$tmp2->row["y"];
                if(in_array($tmp->row["camara_id"], $camaras_pasadas)){
                    $valores = array_count_values($camaras_pasadas);
                    $created.=" (".($valores[$tmp->row["camara_id"]]+1).")";
                    $y=$y+($valores[$tmp->row["camara_id"]]*10);
                }
                
                $return.=$tmp->row["id"].",,".$created;
                $return.=",,".$tmp2->row["x"].",,".$y.";;";

                $camaras_pasadas[]=$tmp->row["camara_id"];
                
                if($tmp2->row["salida"]==1){
                    //echo "salida\n";
                    $esta_dentro=false;
                }
            }while($tmp->Siguiente() and $esta_dentro);
        }
  
        
        
        echo $return;
        
        break;
        
    case "2":
        $return="";
        $camara_id1=$_GET["camara_id1"];
        $camara_id2=$_GET["camara_id2"];
        
        $sql->Consultar('nodos','*',"camara_id1=".$camara_id1." and camara_id2=".$camara_id2." or "."camara_id2=".$camara_id1." and camara_id1=".$camara_id2,"orden asc");
        if($sql->num>0){
            do {
               $return.=$sql->row["x"].",".$sql->row["y"].";;;";
            }while($sql->Siguiente());
        }
        $return= substr($return, 0, (strlen($return)-3));
        echo $return;
        
        break;
        
        
        
    default:
        break;
        
}
